import {opportunity,sideJob} from './events.mjs';
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>(n<0?'−':'+')+'$'+Math.abs(n||0).toLocaleString('en-US',{maximumFractionDigits:2});
export function monthlyHTML(r,lang='vi'){const report=r?.monthly?.portfolio;if(!report?.changes?.length)return '';const vi=lang==='vi';return `<details class="monthly-portfolio" open><summary>${vi?'Diễn biến danh mục tháng':'Portfolio update — month'} ${r.month||r.monthly.month||''}</summary><p>${vi?'Cập nhật thường tháng, trước sự kiện ô. Lãi/lỗ giá trị chưa phải tiền đã bán; phân phối tiền mặt được ghi riêng.':'Regular update before the landing event. Valuation changes are unrealized; cash distributions are separate.'}</p>${report.changes.map(p=>`<div class="monthly-asset"><strong>${esc(opportunity(p.id)[lang][0])}</strong><span>${money(p.change)} (${(p.rate*100).toFixed(2)}%)</span><small>${vi?'Tiền mặt phân phối':'Cash distributed'}: ${money(p.cash)}</small></div>`).join('')}<p><b>${vi?'Tổng':'Total'}: ${money(report.change)} ${vi?'giá trị':'valuation'} · ${money(report.distribution)} ${vi?'tiền mặt':'cash'}</b></p><p>${vi?'Cân nhắc: luận điểm có thay đổi không, có cần tiền sớm không, tỷ trọng có vượt giới hạn không? Một tháng giảm chưa đủ để kết luận phải bán, và giữ mãi cũng không tự động đúng.':'Consider: has your thesis changed, do you need cash soon, and are weights above your limits? One down month does not automatically justify selling; holding forever is not automatically right either.'}</p></details>`;}
export function jobHTML(e,lang='vi'){const job=sideJob(e?.incomeId);return `<h2>${esc(job[lang][0])}</h2><p>${esc(job[lang][1])}</p><span class="amount">${money(job.amount)}</span>`;}
